```go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

type Item struct {
	ID int `json:"id"`
}

func main() {
	dec := json.NewDecoder(strings.NewReader(`{"id":1}
{"id":2}
`))
	for {
		var item Item
		err := dec.Decode(&item)
		if err == io.EOF {
			break
		}
		if err != nil {
			panic(err)
		}
		fmt.Println(item.ID)
	}
}
```
Repeated Decode is correct because this input is intentionally a sequence rather than one HTTP document.

```go
package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

func main() {
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprintln(w, r.Method, r.Header.Get("Authorization")) }))
	defer s.Close()
	req, err := http.NewRequest(http.MethodPut, s.URL, nil)
	if err != nil {
		panic(err)
	}
	req.Header.Set("Authorization", "Bearer test-token")
	resp, err := s.Client().Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		panic(err)
	}
	fmt.Printf("%d %s", resp.StatusCode, body)
}
```
A custom method and header require an explicit Request; the test server observes the actual protocol message.

```go
package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
)

func hello(w http.ResponseWriter, _ *http.Request) {
	w.WriteHeader(http.StatusAccepted)
	fmt.Fprint(w, "hello")
}

func main() {
	rec := httptest.NewRecorder()
	hello(rec, httptest.NewRequest(http.MethodGet, "/", nil))
	fmt.Println("handler:", rec.Code)
	s := httptest.NewServer(http.HandlerFunc(hello))
	defer s.Close()
	resp, err := s.Client().Get(s.URL)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	fmt.Println("server:", resp.StatusCode)
}
```
The first assertion boundary is one function call; the second sends a real HTTP request through the test client's Transport.
